globalThis.YiwuComputer = (() => {
  'use strict';
  const E=Yiwu,VALUE={king:60,rook:9,cannon:8,horse:8,pawn:6,guard:6,elephant:6};
  const formations={red:new WeakMap(),black:new WeakMap()};
  function actions(s){
    if(s.phase!=='board')return [];
    const out=[];
    for(const p of s.pieces.filter(p=>p.side===s.turn)){
      for(const m of E.moves(s,p))out.push({type:'move',id:p.id,x:m.x,y:m.y});
      for(const card of p.exhausted)out.push({type:'rest',id:p.id,card});
    }
    return out;
  }
  function choices(s,p,ctx){return Object.keys(E.BASE).concat(p.learned).filter(id=>!E.availability(s,p,id,ctx));}
  function battleOutlook(s,ctx){
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d),rows=choices(s,a,ctx),cols=choices(s,d,ctx);
    const matrix=rows.map(id=>cols.map(reply=>E.roundDamage(ctx,id,reply)));
    const finishes=rows.filter((_,i)=>matrix[i].every(r=>r.toD>=d.hp&&r.toA<a.hp));
    const counters=cols.filter((_,j)=>matrix.every(row=>row[j].toA>=a.hp&&row[j].toD<d.hp));
    // 确定首轮终结的交换按实际损血和存活价值计算，与站位评分的生命权重一致。
    const score=Math.max(...matrix.map(row=>Math.min(...row.map(r=>
      (Math.min(d.hp,r.toD)*VALUE[d.kind]-Math.min(a.hp,r.toA)*VALUE[a.kind])/36+.8
      +(r.toD>=d.hp?VALUE[d.kind]*.5:0)-(r.toA>=a.hp?VALUE[a.kind]*.5:0)))));
    return {finishes,counters,score};
  }
  function combatOutcome(s,ctx,aId,dId){
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d),r=E.roundDamage(ctx,aId,dId);
    if(ctx.round<6&&r.toA<a.hp&&r.toD<d.hp)return null;
    // 重复局面只保存数字计数，单独复制可避免反复序列化长键。
    const next=JSON.parse(JSON.stringify({...s,phase:'duel',duel:ctx,repetitions:null}));
    next.repetitions={...s.repetitions};
    E.resolve(next,aId,dId);return next.phase==='ended'?next:null;
  }
  function winningChoices(s,ctx,side){
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d),isA=a.side===side,mine=isA?a:d,enemy=isA?d:a;
    if(enemy.kind!=='king'&&!E.CHALLENGES[s.scenario])return [];
    const replies=choices(s,enemy,ctx);
    return choices(s,mine,ctx).filter(id=>replies.every(other=>{
      if(E.CHALLENGES[s.scenario])return combatOutcome(s,ctx,isA?id:other,isA?other:id)?.winner===side;
      const r=E.roundDamage(ctx,isA?id:other,isA?other:id);
      return (isA?r.toD:r.toA)>=enemy.hp&&(mine.kind!=='king'||(isA?r.toA:r.toD)<mine.hp);
    }));
  }
  function kingLostNext(s,side,twoRounds=true){
    if(s.phase!=='board')return false;
    const king=s.pieces.find(p=>p.side===side&&p.kind==='king');
    return s.pieces.some(p=>{
      if(p.side===side||!E.canMove(s,p,king.x,king.y))return false;
      const ctx=E.context(s,p,king);
      if(winningChoices(s,ctx,p.side).length)return true;
      return twoRounds&&twoRoundWinningChoices({...s,turn:p.side,phase:'duel',duel:ctx},p.side).length>0;
    });
  }
  function captureLosesKing(s,ctx,finishes){
    if(s.phase!=='board'||!finishes.length||E.CHALLENGES[s.scenario])return false;
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    return finishes.every(id=>choices(s,d,ctx).every(reply=>{
      const next=JSON.parse(JSON.stringify(s));E.move(next,a.id,d.x,d.y);E.resolve(next,id,reply);
      return kingLostNext(next,a.side);
    }));
  }
  function retreatOutcome(s){
    if(s.phase!=='duel'||s.duel.round<2)return null;
    const next=JSON.parse(JSON.stringify({...s,repetitions:null}));next.repetitions={...s.repetitions};
    E.retreat(next);
    return next.phase==='ended'?next:null;
  }
  function twoRoundWinningChoices(s,side){
    if(s.phase!=='duel'||!s.duel||s.duel.round>=6||E.CHALLENGES[s.scenario])return [];
    const ctx=s.duel,a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    if(a.side!==side||d.kind!=='king')return [];
    // 守方始终能用基础招式反制，每轮至多承受 1 点伤害，首轮另有 1 点突袭。
    if(d.hp>(ctx.round===1?3:2))return [];
    const replies=choices(s,d,ctx);
    return choices(s,a,ctx).filter(id=>replies.every(reply=>{
      const next=JSON.parse(JSON.stringify({...s,repetitions:null}));next.repetitions={...s.repetitions};
      E.resolve(next,id,reply);
      return next.phase==='ended'?next.winner===side:next.phase==='duel'&&winningChoices(next,next.duel,side).length>0;
    }));
  }
  function combatScore(s,ctx,aId,dId){
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    const end=combatOutcome(s,ctx,aId,dId);
    if(end)return end.winner==='draw'?0:end.winner===a.side?1000:-1000;
    const r=E.roundDamage(ctx,aId,dId),wa=a.kind==='king'?3:1,wd=d.kind==='king'?3:1;
    const deadA=r.toA>=a.hp,deadD=r.toD>=d.hp;
    const casualty=(p,dead)=>dead?(p.kind==='king'?1000:8):0;
    return Math.min(d.hp,r.toD)*wd-Math.min(a.hp,r.toA)*wa+casualty(d,deadD)-casualty(a,deadA)
      +(ctx.round<6&&!deadA&&!deadD?1.1*(r.forceAfterA-r.forceAfterD):0)
      +(E.CARDS[dId] ? .25 : 0)-(E.CARDS[aId] ? .25 : 0);
  }
  function distribution(regret){const sum=regret.reduce((n,r)=>n+Math.max(0,r),0);return regret.map(r=>sum?Math.max(0,r)/sum:1/regret.length);}
  function endingCardReplacements(s,side,ids){
    const bases=ids.filter(id=>E.BASE[id]),replacements=new Map();
    if(!bases.length||!ids.some(id=>E.CARDS[id]))return replacements;
    const ctx=s.duel,a=E.get(s,ctx.a),d=E.get(s,ctx.d),isA=a.side===side,mine=isA?a:d,enemy=isA?d:a,replies=choices(s,enemy,ctx),cache=new Map();
    function outcomes(id){
      if(!cache.has(id))cache.set(id,replies.map(reply=>{
        const r=E.roundDamage(ctx,isA?id:reply,isA?reply:id);
        if((isA?r.toA:r.toD)>=mine.hp||ctx.round<6&&(isA?r.toD:r.toA)<enemy.hp)return null;
        const next=JSON.parse(JSON.stringify({...s,repetitions:null}));next.repetitions={...s.repetitions};
        E.resolve(next,isA?id:reply,isA?reply:id);
        const survivor=E.get(next,mine.id);
        return {hp:survivor.hp,key:E.key({...next,pieces:next.pieces.map(p=>p.id===mine.id?{...p,hp:0,exhausted:[]}:p)}),phase:next.phase,winner:next.winner,reason:next.reason,quiet:next.quiet,visits:next.repetitions[E.key(next)]||0};
      }));
      return cache.get(id);
    }
    // 只省下所有回应下都能以相同局面结束交战、且不多损血或增加重复风险的培养牌。
    for(const id of ids.filter(id=>E.CARDS[id])){
      const base=bases.find(base=>outcomes(base).every((next,i)=>{
        const used=outcomes(id)[i];
        return next&&used&&next.hp>=used.hp&&next.key===used.key&&next.phase===used.phase&&next.winner===used.winner&&next.reason===used.reason&&next.quiet===used.quiet&&next.visits<=used.visits;
      }));
      if(base)replacements.set(id,base);
    }
    return replacements;
  }
  function combatPlan(s,side){
    if(s.phase!=='duel'||!s.duel)throw new Error('当前没有武斗');
    const ctx=s.duel,a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    if(side!==a.side&&side!==d.side)throw new Error('无效阵营');
    const winning=winningChoices(s,ctx,side);
    if(winning.length)return winning.map(id=>({id,weight:1/winning.length}));
    const end=retreatOutcome(s);
    if(side===a.side&&end?.winner===side)return [{id:'retreat',weight:1}];
    const twoRound=twoRoundWinningChoices(s,side);
    if(twoRound.length)return twoRound.map(id=>({id,weight:1/twoRound.length}));
    const isA=side===a.side,loses=id=>(E.CHALLENGES[s.scenario]||(isA?a:d).kind==='king')&&id!=='retreat'&&choices(s,isA?d:a,ctx).every(other=>
      combatOutcome(s,ctx,isA?id:other,isA?other:id)?.winner===E.OTHER[side]);
    if(ctx.round===1){
      const opening=battleOutlook(s,ctx);
      let safe=(isA?opening.finishes:opening.counters).filter(id=>!loses(id));
      if(isA&&a.kind==='king'&&safe.length>1){
        const replies=choices(s,d,ctx);
        // 先排除一轮败局，再避开两轮败局；不能因全部两轮不安全而重新放回一轮必败招式。
        for(const twoRounds of [false,true]){
          const protectedChoices=safe.filter(id=>replies.every(reply=>{
            const next=JSON.parse(JSON.stringify(s));E.resolve(next,id,reply);
            return !kingLostNext(next,side,twoRounds);
          }));
          if(protectedChoices.length)safe=protectedChoices;
          if(safe.length===1)break;
        }
      }
      const replacements=endingCardReplacements(s,side,safe);safe=safe.filter(id=>!replacements.has(id));
      if(safe.length)return safe.map(id=>({id,weight:1/safe.length}));
    }
    const rows=choices(s,a,ctx),cols=choices(s,d,ctx);
    if(ctx.round>=2&&end?.winner!==d.side)rows.push('retreat');
    const retreatScore=end?.winner==='draw'?0:end?.winner===a.side?1000:-.6;
    const matrix=rows.map(x=>cols.map(y=>x==='retreat'?retreatScore:combatScore(s,ctx,x,y))),ra=rows.map(()=>0),rd=cols.map(()=>0),sa=rows.map(()=>0),sd=cols.map(()=>0);
    // shortcut: 仅对进攻将帅核对两轮确定胜局；需要更高难度时再扩大后续轮次搜索。
    for(let n=0;n<160;n++){
      const pa=distribution(ra),pd=distribution(rd),va=rows.map((_,i)=>cols.reduce((v,__,j)=>v+matrix[i][j]*pd[j],0));
      const vd=cols.map((_,j)=>rows.reduce((v,__,i)=>v+matrix[i][j]*pa[i],0)),v=va.reduce((v,x,i)=>v+x*pa[i],0);
      rows.forEach((_,i)=>{ra[i]+=va[i]-v;sa[i]+=pa[i];});cols.forEach((_,j)=>{rd[j]+=v-vd[j];sd[j]+=pd[j];});
    }
    const mine=side===a.side?rows:cols,weights=(side===a.side?sa:sd).map(n=>n/160);
    const recent=ctx.history.slice(-2),typeKey=side===a.side?'dType':'aType';
    if(recent.length===2&&recent[0][typeKey]===recent[1][typeKey]){
      const enemy=side===a.side?cols:rows,seen=recent[1][typeKey];
      const matching=enemy.map((id,i)=>({id,i})).filter(x=>(E.BASE[x.id]||E.CARDS[x.id])?.type===seen);
      if(matching.length){
        const response=mine.map((_,i)=>matching.reduce((n,x)=>n+(side===a.side?matrix[i][x.i]:-matrix[x.i][i]),0)/matching.length),best=Math.max(...response),ties=response.filter(v=>v>=best-.01).length;
        weights.forEach((v,i)=>{weights[i]=v*.65+(response[i]>=best-.01 ? .35/ties : 0);});
      }
    }
    const plan=mine.map((id,i)=>({id,weight:weights[i]}));let kept=plan.filter(x=>!loses(x.id));
    if((isA?a:d).kind==='king'){
      const replies=choices(s,isA?d:a,ctx),safe=kept.filter(x=>x.id==='retreat'?end?.winner!==E.OTHER[side]:replies.every(other=>
        combatOutcome(s,ctx,isA?x.id:other,isA?other:x.id)?.winner!==E.OTHER[side]));
      // 有本轮不判负的选择时，去掉迭代残留的冒险概率。
      if(safe.length){
        kept=safe;
        if(!isA&&ctx.round<6&&!E.CHALLENGES[s.scenario]){
          // 守将本轮有不判负的选择时，再避开会留下下一轮确定败局的招式。
          const protectedChoices=kept.filter(x=>replies.every(other=>{
            // 下一轮没有突袭，基础克制招可将来伤压到 1 点；只试算会剩 1 血的分支。
            if(E.roundDamage(ctx,other,x.id).toD!==d.hp-1)return true;
            const next=JSON.parse(JSON.stringify({...s,repetitions:null}));next.repetitions={...s.repetitions};
            E.resolve(next,other,x.id);
            return next.phase!=='duel'||!winningChoices(next,next.duel,a.side).length;
          }));
          if(protectedChoices.length)kept=protectedChoices;
        }
      }
    }
    const replacements=endingCardReplacements(s,side,kept.map(x=>x.id));
    for(const [id,base]of replacements)kept.find(x=>x.id===base).weight+=kept.find(x=>x.id===id).weight;
    kept=kept.filter(x=>!replacements.has(x.id));
    if(kept.length&&kept.length<plan.length){const total=kept.reduce((n,x)=>n+x.weight,0);return kept.map(x=>({id:x.id,weight:x.weight/total}));}
    return plan;
  }
  function sample(list,rng){let roll=rng();for(const item of list){roll-=item.weight;if(roll<=0)return item.id;}return list[list.length-1].id;}
  function practicePlan(s,side){
    if(s.phase!=='duel'||!s.duel)throw new Error('当前没有武斗');
    const ctx=s.duel,a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    if(side!==a.side&&side!==d.side)throw new Error('无效阵营');
    const p=side===a.side?a:d;
    if(p===a&&ctx.round>=2){
      const end=retreatOutcome(s);
      if(end?.winner===side||p.hp<=4&&end?.winner!==d.side)return [{id:'retreat',weight:1}];
    }
    const ids=choices(s,p,ctx),types=[...new Set(ids.map(id=>(E.BASE[id]||E.CARDS[id]).type))];
    return ids.map(id=>({id,weight:1/types.length/ids.filter(other=>(E.BASE[other]||E.CARDS[other]).type===(E.BASE[id]||E.CARDS[id]).type).length}));
  }
  function combat(s,side,rng=Math.random,difficulty='standard'){return sample(difficulty==='practice'?practicePlan(s,side):combatPlan(s,side),rng);}
  function explain(id,difficulty='standard',s){
    if(id==='retreat'){
      const end=s.phase==='ended'?s:retreatOutcome(s);
      return (end?'撤回直接结束本局：'+(end.winner==='draw'?'判和':E.SIDE[end.winner]+'获胜')+'。'+end.reason:'主动撤回以保留棋子和当前生命，不再结算本轮伤害。')+'伤势与耗尽牌保留，气势清零。';
    }
    const c=E.BASE[id]||E.CARDS[id];
    return (difficulty==='practice'?'练习电脑在可用招式类型之间等概率选择，再从该类中选一招；不针对历史出招调整。':'标准电脑优先抓住可确认的获胜机会，进攻将帅时还会核对两轮确定胜局；其他局面依据公开状态评估本轮收益，并参考已揭示的出招历史。')+'本轮选择「'+c.name+'」：'+c.text;
  }
  function bothCanEndWithoutLosing(s,ctx){
    const a=E.get(s,ctx.a),d=E.get(s,ctx.d);
    if(a.kind!=='king'||d.kind!=='king'||E.CHALLENGES[s.scenario])return false;
    const rows=choices(s,a,ctx),cols=choices(s,d,ctx);
    const ends=rows.map(id=>cols.map(reply=>combatOutcome(s,ctx,id,reply)));
    return ends.some(row=>row.every(end=>end&&end.winner!==d.side))
      &&cols.some((_,j)=>ends.every(row=>row[j]&&row[j].winner!==a.side));
  }
  function threatCost(s,p,repeated=false){
    let enemies=s.pieces.filter(q=>q.side!==p.side&&E.geometry(s,q,p.x,p.y,true));
    if(E.CHALLENGES[s.scenario]&&p.kind==='king'&&p.side==='black')enemies=[];
    if(p.kind==='king'&&!E.CHALLENGES[s.scenario])enemies=enemies.filter(q=>!battleOutlook(s,E.context(s,q,p)).counters.length);
    if(!enemies.length)return 0;
    const guards=E.support(s,p,p.x,p.y,[p.id]).length;
    return VALUE[p.kind]*(p.kind==='king'?(repeated?.07:.7):.14)*(1+Math.max(0,12-p.hp)/12)/(1+Math.min(2,guards)*.4);
  }
  function position(s,side,repeated=false){
    let score=0;
    for(const p of s.pieces){
      const sign=p.side===side?1:-1,v=VALUE[p.kind];
      let value=v*(.5+p.hp/36)+.15*(p.learned.length-p.exhausted.length);
      value-=threatCost(s,p,repeated&&p.side!==side);
      if(['rook','horse','cannon','pawn'].includes(p.kind)){
        const targets=s.pieces.filter(q=>q.side!==p.side);
        const distance=targets.length?Math.min(...targets.map(q=>Math.abs(q.x-p.x)+Math.abs(q.y-p.y))):0;
        value+=.07*(9-distance)+.025*(4-Math.abs(p.x-4))+.025*(p.side==='red'?9-p.y:p.y);
      }
      score+=sign*value;
    }
    return score;
  }
  function rankedActions(s){
    const side=s.turn,base=position(s,side);
    const own=new Set(s.pieces.filter(p=>p.side===side).map(p=>p.id)),visits=new Map();
    const signature=JSON.stringify([...own].sort());
    let cached=formations[side].get(s.repetitions);
    if(cached?.signature!==signature){cached={signature,keys:new Map()};formations[side].set(s.repetitions,cached);}
    const formation=key=>{
      const [turn,pieces]=JSON.parse(key);
      return JSON.stringify([turn,pieces.map(([id,x,y,...state])=>own.has(id)?[id,x,y,...state]:[id,...state])]);
    };
    // 仅缓存已有历史的阵形解析，次数实时读取；试算落点不进入缓存。
    for(const [key,count] of Object.entries(s.repetitions)){
      let k=cached.keys.get(key);
      if(k===undefined){k=formation(key);cached.keys.set(key,k);}
      visits.set(k,(visits.get(k)||0)+count);
    }
    return actions(s).map(action=>{
      const p=E.get(s,action.id),next={...s,pieces:s.pieces.map(q=>({...q})),repetitions:{...s.repetitions},log:[...s.log]};
      let score,battle=false;
      if(action.type==='rest'){
        E.rest(next,p.id,action.card);
      }else{
        const target=E.at(s,action.x,action.y);
        if(target){
          battle=true;
          const ctx=E.context(s,p,target),rateA=2.5+.7*(E.power(ctx,true)-3),rateD=2.5+.7*(E.power(ctx,false)-3);
          const rounds=Math.min(6,Math.ceil(target.hp/rateA),Math.ceil(p.hp/rateD)),hurtD=Math.min(target.hp,rateA*rounds+.7),hurtA=Math.min(p.hp,rateD*rounds);
          const valueA=VALUE[p.kind],valueD=VALUE[target.kind];
          score=(hurtD*valueD-hurtA*valueA)/24+.8;
          if(hurtD>=target.hp)score+=valueD*.5;
          if(hurtA>=p.hp)score-=valueA*.5;
          if(target.kind==='king')score+=hurtD*1.3;
          const outlook=battleOutlook(s,ctx);
          if(outlook.finishes.length||outlook.counters.length)score=outlook.score;
          if(!outlook.finishes.length&&!outlook.counters.length&&p.kind!=='king'&&target.kind!=='king'&&!E.CHALLENGES[s.scenario]){
            const a=E.get(next,p.id),d=E.get(next,target.id),king=s.pieces.find(q=>q.side===side&&q.kind==='king');
            a.hp-=hurtA;d.hp-=hurtD;
            if(d.hp<=0&&a.hp>0){a.x=d.x;a.y=d.y;}
            next.pieces=next.pieces.filter(q=>q.hp>0);
            // 预计吃子尚未确认，只计入新增的将帅风险，不提前奖励解除威胁。
            score-=Math.max(0,threatCost(next,king)-threatCost(s,king));
          }
          if(outlook.finishes.length&&!E.CHALLENGES[s.scenario]){
            const replies=choices(s,target,ctx);
            score=Math.max(...outlook.finishes.map(id=>Math.min(...replies.map(reply=>{
              const result=JSON.parse(JSON.stringify({...s,repetitions:null}));result.repetitions={...s.repetitions};
              E.move(result,p.id,target.x,target.y);E.resolve(result,id,reply);
              return result.phase==='ended'?(result.winner==='draw'?-base:result.winner===side?1000:-1000):position(result,side)-base+.8;
            }))));
          }
          if(winningChoices(s,ctx,side).length)score=1000;
          else if(bothCanEndWithoutLosing(s,ctx))score=-base;
          else if(target.kind==='king'&&!E.CHALLENGES[s.scenario]){
            E.move(next,p.id,action.x,action.y);
            if(twoRoundWinningChoices(next,side).length)score=1000;
          }
          if(captureLosesKing(s,ctx,outlook.finishes))score-=1000;
        }else{
          E.move(next,p.id,action.x,action.y);
        }
      }
      if(!battle&&next.phase==='ended')return {...action,score:next.winner==='draw'?-base:next.winner===side?1000:-1000};
      const repeated=battle?0:Math.min(2,visits.get(formation(E.key(next)))||0);
      if(!battle){
        score=position(next,side,repeated>0)-base+(action.type==='rest'?.05:0);
